const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
if (input.length === 0) process.exit(0);

let idx = 0;
const N = Number(input[idx++]);
const Q = Number(input[idx++]);

const bit = new Array(N + 1).fill(0);
const people = new Array(N + 1).fill(0);

function add(i, delta) {
  while (i <= N) {
    bit[i] += delta;
    i += i & -i;
  }
}

function prefixSum(i) {
  let sum = 0;
  while (i > 0) {
    sum += bit[i];
    i -= i & -i;
  }
  return sum;
}

for (let i = 1; i <= N; i++) {
  const v = Number(input[idx++]);
  people[i] = v;
  add(i, v);
}

const output = [];

for (let e = 0; e < Q; e++) {
  const type = Number(input[idx++]);

  if (type === 0) {
    const k = Number(input[idx++]);
    const p = Number(input[idx++]);
    add(k, p - people[k]);
    people[k] = p;
  } else {
    const k = Number(input[idx++]);
    output.push(prefixSum(k));
  }
}

console.log(output.join('\n'));
